                } 
  
    }
     function RegisteredFrom(address _oldCont) onlyOwner external
  {
     oldContract = IOldContract(_oldCont);
  }
  function updatfounder( uint _founderid, uint status) public onlyOwner nonReentrant returns(bool)
     { 
         require(IsFounder[foundermembers[_founderid].founderaddress] == true, "founder not exist !");
         if (status==1 || status==0)
         {
            
           foundermembers[_founderid].isactive = status;  
           foundermembers[_founderid].updatestamp = block.timestamp;  
         }
            return true;
          
    }
  function distributefounderincome(uint fromid , uint toid) public onlyOwner nonReentrant returns(bool)
     {
         require(founderids > 0, "founder required !");
        uint income=topayfounderincome;
        for (fromid; fromid<=toid && toid<=founderids && topayfounderincome<=unpaidfounderincome; fromid++ ) 
        { 
            if (foundermembers[fromid].isactive==0 && foundermembers[fromid].lastpaidtamp + 24 hours  <= block.timestamp) 
            {
                address payaddress=foundermembers[fromid].founderaddress;
