                {
                    uint payincome=2000 * 1e18-foundermembers[fromid].totalincome;
                    foundermembers[fromid].totalincome += payincome;
                    foundermembers[fromid].lastpaidtamp =block.timestamp;
                    require(token.transfer(address(payaddress), income ), "Transfer failed");
                }
                 
                if (foundermembers[fromid].totalincome>=2000 * 1e18)
                {
                    foundermembers[fromid].isactive = 1;  
