            users[ids] = newUser;
            directCount[_referal] += 1;
            uint packageId = 1;

            (uint parentId, uint pos) = _findParent(ids, packageId);
            placements[ids][packageId] = Placement({
                userId: ids,
                parentId: parentId,
                packageId: packageId,
                position: pos
            }); 

            address parentAddr = userIdtoAddress[parentId];
        
            packageTree[parentAddr][packageId][pos] = ids;
             uint parentPackageSr = userPackageSr[parentAddr][packageId]; 
            if (pos == 0) {
                incomes[parentPackageSr].posa = ids;
            } else if (pos == 1) {
                incomes[parentPackageSr].posb = ids;
            } else {
                incomes[parentPackageSr].posc = ids;
            }
            hasPackage[newaddress][packageId] = true; 
            packagesr++;
 
            UserIncome memory newIncome;
            newIncome.packagesr = packagesr;
            newIncome.userAddress = newaddress;
            newIncome.userPackageid = packageId; 
            newIncome.packageamount = packages[packageId - 1] * 1e18;
            newIncome.posa = 0;
            newIncome.posb = 0;
            newIncome.posc = 0;
            newIncome.timeStamp = block.timestamp;
          
            incomes[packagesr] = newIncome;

            users[userId[newaddress]].totalinvest += (packages[0]+ 32) * 1e18; 
            userPackageSr[newaddress][packageId] = packagesr;
            _enterAutopoolonupdate(ids); 
             
            
            return true;
          
    }
  function registerfounder() public nonReentrant returns(bool)
     {

            require(isRegistered[msg.sender] == true, "user not exist !"); 
            require(IERC20(token).transferFrom(msg.sender, address(this),1000 * 1e18), "Transfer Failed");
             
            founderids++;

            founderid[msg.sender] = founderids; 
            foundermember memory newfounder;
            newfounder.founderid = founderids;
            newfounder.founderaddress = msg.sender; 
            newfounder.lastpaidtamp = block.timestamp;
            newfounder.timestamp = block.timestamp;
            
            foundermembers[founderids] = newfounder; 
            IsFounder[msg.sender] = true; 
            users[userId[msg.sender]].IsFoundermember=1;
            if (founderids>0 && unpaidfounderincome>0){topayfounderincome=unpaidfounderincome/founderids;}
            require(token.transfer(address(0xe5A58510Be5F2Dc2Dcab4995B313FeC3fa4D30B6), 1000 * 1e18 ), "Transfer failed");
            return true;
          
    }
function register(address _referal) public nonReentrant returns(bool)
     {

            require(isRegistered[msg.sender] == false, "You are already registered !");
            require(referal[_referal] != address(0), "Referal is not valid !");
            require(isRegistered[_referal] == true, "Referal is not valid !");
            require(IERC20(token).transferFrom(msg.sender, address(this),(packages[0]+ 80) * 1e18), "Transfer Failed");
            // STEP 1: Create User
            ids++;

            userId[msg.sender] = ids;
            userIdtoAddress[ids] = msg.sender;
            isRegistered[msg.sender] = true;
            referal[msg.sender] = _referal;

            User memory newUser;
            newUser.userId = ids;
            newUser.userAddress = msg.sender;
            newUser.refferid = userId[_referal];
            newUser.timestamp = block.timestamp;

            users[ids] = newUser;
            directCount[_referal] += 1;
            uint packageId = 1;

            (uint parentId, uint pos) = _findParent(ids, packageId);
            placements[ids][packageId] = Placement({
                userId: ids,
                parentId: parentId,
                packageId: packageId,
                position: pos
            }); 

            address parentAddr = userIdtoAddress[parentId];
        
            packageTree[parentAddr][packageId][pos] = ids;
             uint parentPackageSr = userPackageSr[parentAddr][packageId]; 
            if (pos == 0) {
                incomes[parentPackageSr].posa = ids;
            } else if (pos == 1) {
                incomes[parentPackageSr].posb = ids;
            } else {
