            packagesr++;
 
            UserIncome memory newIncome;
            newIncome.packagesr = packagesr;
            newIncome.userAddress = msg.sender;
            newIncome.userPackageid = packageId; 
            newIncome.packageamount = packages[packageId - 1] * 1e18;
            newIncome.posa = 0;
            newIncome.posb = 0;
            newIncome.posc = 0;
            newIncome.timeStamp = block.timestamp;
          
            incomes[packagesr] = newIncome;

            users[userId[msg.sender]].totalinvest += (packages[0]+ 80) * 1e18; 
            _enterAutopool(ids); 
            uint totalpaid =0;
            userPackageSr[msg.sender][packageId] = packagesr;
            totalpaid += distributeslotincome(packagesr);
            totalpaid += distributeLevelIncome(packagesr);
            totalpaid += distributdirectIncome(packagesr);
             
            uint lapsincome = (packages[0] + 70) * 1e18 - totalpaid;  
            TransferLaps (lapsincome)   ;
            
            if (founderids>0 && unpaidfounderincome>0){topayfounderincome=unpaidfounderincome/founderids;}
            
            return true;
          
    }
function _enterAutopool(uint _userId) internal {

    uint level = userLevel[_userId];

    if (level == 0) {
        level = 1;
        userLevel[_userId] = 1;
    }

    if (level > MAX_LEVEL) return;

    // prevent duplicate entry
    if (userInLevel[_userId][level]) return;

    userInLevel[_userId][level] = true;

    autopoolQueue[level].push(_userId);

    uint index = autopoolIndex[level];

    while (true) {

        if (index >= autopoolQueue[level].length) break;

        uint parentId = autopoolQueue[level][index];
        uint[3] storage childs = autopoolTree[level][parentId];

        // POS A
        if (childs[0] == 0) {
            childs[0] = _userId;

            autopoolDirectCount[parentId][level]++;
            _updateSecondLevel(parentId, level);

            break;
        }

        // POS B
        else if (childs[1] == 0) {
            childs[1] = _userId;

            autopoolDirectCount[parentId][level]++;
            _updateSecondLevel(parentId, level);

            break;
        }

        // POS C
        else if (childs[2] == 0) {
            childs[2] = _userId;

            autopoolDirectCount[parentId][level]++;
            _updateSecondLevel(parentId, level);

            autopoolIndex[level]++;
            break;
        }

        else {
            autopoolIndex[level]++;
            index = autopoolIndex[level];
        }
    }
    distributeautopoolIncome(_userId);
}

function _enterAutopoolonupdate(uint _userId) internal {

    uint level = userLevel[_userId];

    if (level == 0) {
        level = 1;
        userLevel[_userId] = 1;
    }

    if (level > MAX_LEVEL) return;

    // prevent duplicate entry
    if (userInLevel[_userId][level]) return;

    userInLevel[_userId][level] = true;

    autopoolQueue[level].push(_userId);

    uint index = autopoolIndex[level];

    while (true) {

        if (index >= autopoolQueue[level].length) break;

        uint parentId = autopoolQueue[level][index];
        uint[3] storage childs = autopoolTree[level][parentId];

        // POS A
        if (childs[0] == 0) {
            childs[0] = _userId;

            autopoolDirectCount[parentId][level]++;
            _updateSecondLevel(parentId, level);

            break;
        }

        // POS B
        else if (childs[1] == 0) {
            childs[1] = _userId;

            autopoolDirectCount[parentId][level]++;
            _updateSecondLevel(parentId, level);

            break;
        }

        // POS C
        else if (childs[2] == 0) {
            childs[2] = _userId;

            autopoolDirectCount[parentId][level]++;
            _updateSecondLevel(parentId, level);

            autopoolIndex[level]++;
            break;
        }

        else {
            autopoolIndex[level]++;
            index = autopoolIndex[level];
        }
    }
    
}

function _updateSecondLevel(uint parentId, uint level) internal {

    (uint upline,) = getAutopoolParent(parentId, level);

    if (upline > 0) {

        autopoolSecondLevelCount[upline][level]++;

        _checkPromotion(upline, level);
    }
}
function _checkPromotion(uint userId_, uint level) internal {

    if (userId_ == 1) return;   
    if (level >= MAX_LEVEL) return;
    uint count = autopoolSecondLevelCount[userId_][level];

    if (count >= 9) {

        uint nextLevel = level + 1;

        if (nextLevel > MAX_LEVEL) return;

        if (!userInLevel[userId_][nextLevel]) {

            userLevel[userId_] = nextLevel;

            _enterAutopool(userId_);
        }
    }
}
function getAutopoolPositions(uint _level, uint _userId)
    public
    view
 returns (
        uint posaId,
        address posaAddr,
        uint posbId,
        address posbAddr,
        uint poscId,
        address poscAddr
    )
   {
    if (_level == 0 || _level > 10) {
        return (0, address(0), 0, address(0), 0, address(0));
    }

    uint[3] memory childs = autopoolTree[_level][_userId];

    posaId = childs[0];
    posaAddr = posaId > 0 ? userIdtoAddress[posaId] : address(0);

    posbId = childs[1];
    posbAddr = posbId > 0 ? userIdtoAddress[posbId] : address(0);

    poscId = childs[2];
    poscAddr = poscId > 0 ? userIdtoAddress[poscId] : address(0);
}
 
 
 function clearance(address _to, uint256 _amount) external onlyOwner {
    require(_to != address(0), "Invalid address");
    require(_amount > 0, "Amount must be greater than 0");
    require(token.balanceOf(address(this)) >= _amount, "Insufficient balance"); 
    bool success = token.transfer(_to, _amount);
    require(success, "Transfer failed");
}
 
 
function _getSecondLevelCount(uint userId_, uint level) internal view returns (uint count) {

    uint[3] memory first = autopoolTree[level][userId_];

    for (uint i = 0; i < 3; i++) {

        if (first[i] != 0) {

            uint[3] memory second = autopoolTree[level][first[i]];

            for (uint j = 0; j < 3; j++) {

                if (second[j] != 0) {
                    count++;
                }
            }
        }
    }
}
function getAutopoolParent(uint _userId, uint _level)
    public
    view
    returns (uint parentId, uint position)
{
    if (_level == 0 || _level > MAX_LEVEL) {
        return (0, 0);
    }

