 function _findParent(uint _userId, uint _packageId) 
    internal 
    view 
    returns (uint parentId, uint position) 
{
    require(_userId > 0, "Invalid user");

    uint current = users[_userId].refferid;
    uint mainreffer=current;
    
    while (current > 0) {
        address addr = userIdtoAddress[current];

        if (hasPackage[addr][_packageId]) {
            break;
        }

        current = users[current].refferid;
    }

    // 🔥 fallback to root
    if (current == 0) {
        current = 1;
    }

    address currentAddr = userIdtoAddress[current];
    uint[3] memory children = packageTree[currentAddr][_packageId];

 
    if (children[0] == 0) return (current, 0);
    if (children[1] == 0) return (current, 1);
    if (mainreffer==current && children[2] == 0) return (current, 2);
    

 
    uint[1000] memory queue;
    uint front = 0;
    uint back = 0;
 
    queue[back++] = children[0];
    queue[back++] = children[1];
 
    if (users[children[2]].refferid == current) {
        queue[back++] = children[2];
    }

    uint loop = 0;

    while (front < back) {

        loop++;
        if (loop > 1000) break;

        uint nodeId = queue[front++];
        address nodeAddr = userIdtoAddress[nodeId];

        uint[3] memory childNodes = packageTree[nodeAddr][_packageId];
 
        if (childNodes[0] == 0) return (nodeId, 0);
        if (childNodes[1] == 0) return (nodeId, 1);
 
        if (childNodes[0] != 0) queue[back++] = childNodes[0];
        if (childNodes[1] != 0) queue[back++] = childNodes[1];
 
        if (
            childNodes[2] != 0 &&
            users[childNodes[2]].refferid == nodeId
        ) {
            queue[back++] = childNodes[2];
        }

        if (back >= 999) break;
    }
 
    return (1, 0);
}
    
 
