 function distributeslotincome(uint _packageSr) internal  returns (uint paid) {

    // STEP 1: Get user + package details
    address userAddr = incomes[_packageSr].userAddress;
    uint currentUser = userId[userAddr];
    uint packageId = incomes[_packageSr].userPackageid;
    uint amount = incomes[_packageSr].packageamount;
    paid=0;
    uint retop=0;
    uint loop = 0;

    while (true) {

        loop++;
        require(loop < 50, "Loop overflow");

        // STEP 2: Get placement
        Placement memory p = placements[currentUser][packageId];
        
        uint parentId = p.parentId;
        uint position = p.position;
        if (parentId == 0) break;
        
        uint orgreffer=0; 
           if (retop==0) 
           {
              orgreffer= users[userId[userAddr]].refferid; 
           }
           else 
           {
                orgreffer=users[currentUser].refferid;
                
           }
        // STEP 3: If position is A (0) or B (1)
       

         if (position == 0 || position == 1) {
           
           
            address orgrefferaddr= userIdtoAddress[orgreffer];
           
             uint income1 = (amount * 25) / 100;
           
             uint checkno=packageTree[orgrefferaddr][packageId][2];
            if (checkno==0 &&  retop>0)
            {
                    income1=0;
            }
            if (orgreffer>13 && income1>0)
            {
                require(token.transfer(address(orgrefferaddr),income1), "Transfer failed");
                paid+=income1;
            }
            users[orgreffer].totaldirectincome += income1;
            AllIncomesr++;
            AllIncome[AllIncomesr] = AllIncomedata({    
                AllIncomesr: AllIncomesr,
                userid: orgreffer,
                userAddress: orgrefferaddr,
                ByuserAddress: userAddr,
                incomeamount: income1,
                bylevel: 1,
                IncomeByType: 1,
                incomeper: 25,
                timeStamp: block.timestamp
            });

            // STEP 4: Parent of parent
            Placement memory p2 = placements[parentId][packageId];
            uint parent2Id = p2.parentId;

            if (parent2Id > 0) {

                address parent2Addr = userIdtoAddress[parent2Id];
            
                uint income2 = (amount * 75) / 100;
              checkno=packageTree[parent2Addr][packageId][2];
           if (checkno==0 &&  retop>0)
            {
                    income2=0;
            }
           if (parent2Id>13 && income2>0)
            { 
                require(token.transfer(address(parent2Addr),income2), "Transfer failed");
                paid+=income2;
            }
                users[parent2Id].totalslotincome +=income2;
                AllIncomesr++;
                AllIncome[AllIncomesr] = AllIncomedata({
                    AllIncomesr: AllIncomesr,
                    userid: parent2Id,
                    userAddress: parent2Addr,
                    ByuserAddress: userAddr,
                    incomeamount: income2,
                    bylevel: 2,
                    IncomeByType: 2,
                    incomeper: 75,
                    timeStamp: block.timestamp
                });
            }

            break; // STOP after distribution
        }

        // STEP 5: If position is C (2) → move up
        else if (position == 2) {
            
            users[orgreffer].retopupcount += 1;  
            userPackageRetopup[orgreffer][packageId] += 1;
            retop+=1;
            currentUser = orgreffer;
        }

        // safety fallback
        else {
            break;
        }
    }
    return paid;
}

