function importUsers(uint fromId, uint toId)
    external
    onlyOwner
{
    require(address(oldContract) != address(0), "Old contract not set");

    for(uint i = fromId; i <= toId; i++) {

        // SKIP ROOT USER
        if(i == 1) {
            continue;
        }

        (
            uint uid,
            address userAddress,
            uint refferid,
            uint totalinvest,
            uint totalslotincome,
            uint totaldirectincome,
            uint totallevelincome,
            uint totalautopoolincome,
            uint retopupcount,
            uint IsFoundermember,
            uint timestamp
        ) = oldContract.users(i);

        // SKIP EMPTY USERS
        if(userAddress == address(0)) {
            continue;
        }

        // PREVENT DUPLICATE
        if(isRegistered[userAddress]) {
            continue;
        }

        // SAVE USER
        users[uid] = User({
            userId: uid,
            userAddress: userAddress,
            refferid: refferid,
            totalinvest: totalinvest,
            totalslotincome: totalslotincome,
            totaldirectincome: totaldirectincome,
            totallevelincome: totallevelincome,
            totalautopoolincome: totalautopoolincome,
            retopupcount: retopupcount,
            IsFoundermember: IsFoundermember,
            timestamp: timestamp
        });

        // SAVE MAPPINGS
        userId[userAddress] = uid;
        userIdtoAddress[uid] = userAddress;

        referal[userAddress] =
            oldContract.referal(userAddress);

        isRegistered[userAddress] = true;

        // IMPORTANT FIX
        directCount[userAddress] =
            oldContract.directCount(userAddress);

        // IMPORT LEVEL
        userLevel[uid] =
            oldContract.userLevel(uid);

        // IMPORTANT
        if(uid > ids) {
            ids = uid;
        }
    }
}

